/**
 * retrieval promptfoo output vs committed snapshot parity test (PostgreSQL-backed).
 *
 * The committed snapshot (`evals/promptfoo/snapshots/retrieval-smoke.json`) was
 * generated by running the retrieval bridge through the promptfoo engine against
 * a postgres-coordinated temporary database. Retrieval execution drives the real
 * composed server (adapters require TRAPMAP_DATABASE_URL), so this test
 * provisions a temporary database from TRAPMAP_POSTGRES_COORDINATOR_URL (same
 * mechanism as run-postgres-coordinated), runs the six owner migrations, then
 * re-runs the same bridge + opts and asserts the per-case judgment (caseId +
 * passed + hitAt1/mrr/ndcg) reproduces the committed snapshot. Skips when the
 * coordinator URL is absent.
 */

import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';

import pg from 'pg';
import { beforeAll, afterAll, describe, expect, it } from 'vitest';

import { runCandidateIngestionMigrations } from '../../packages/service-candidate-ingestion/src/migrations.js';
import { runGovernanceReviewMigrations } from '../../packages/service-governance-review/src/migrations.js';
import { runIdentityAccessMigrations } from '../../packages/service-identity-access/src/migrations.js';
import { runJobRuntimeMigrations } from '../../packages/service-job-runtime/src/migrations.js';
import { runKnowledgeReadMigrations } from '../../packages/service-knowledge-read/src/migrations.js';
import { runKnowledgeWriteMigrations } from '../../packages/service-knowledge-write/src/migrations.js';

import { retrievalBridge } from '../retrieval/bridge.js';
import { getSnapshotSuiteConfigs, snapshotFilePath } from './scripts/generate-snapshots.js';
import { runSuiteWithPromptfoo } from './runner.js';
import { suiteSnapshotSchema } from './snapshots/snapshot-schema.js';

const migrations = [
  runIdentityAccessMigrations,
  runKnowledgeWriteMigrations,
  runCandidateIngestionMigrations,
  runGovernanceReviewMigrations,
  runJobRuntimeMigrations,
  runKnowledgeReadMigrations,
] as const;

const coordinatorUrl = process.env.TRAPMAP_POSTGRES_COORDINATOR_URL;
const databaseName = `trapmap_parity_${randomUUID().replace(/-/g, '')}`;
let databaseUrl: string | undefined;
const priorDatabaseUrl = process.env.TRAPMAP_DATABASE_URL;

function databaseUrlFromAdmin(adminUrl: string, name: string): string {
  const url = new URL(adminUrl);
  url.pathname = `/${name}`;
  return url.toString();
}

async function provision(): Promise<void> {
  if (!coordinatorUrl) throw new Error('TRAPMAP_POSTGRES_COORDINATOR_URL is required');

  const adminPool = new pg.Pool({ connectionString: coordinatorUrl });
  try {
    await adminPool.query(`CREATE DATABASE "${databaseName}"`);
  } finally {
    await adminPool.end();
  }

  databaseUrl = databaseUrlFromAdmin(coordinatorUrl, databaseName);
  const pool = new pg.Pool({ connectionString: databaseUrl });
  try {
    for (const migrate of migrations) await migrate(pool);
    const extension = await pool.query("SELECT extname FROM pg_extension WHERE extname = 'vector'");
    if (extension.rowCount !== 1) {
      throw new Error('temporary database is missing the vector extension');
    }
  } finally {
    await pool.end();
  }
  process.env.TRAPMAP_DATABASE_URL = databaseUrl;
}

async function teardown(): Promise<void> {
  if (coordinatorUrl && databaseUrl) {
    const adminPool = new pg.Pool({ connectionString: coordinatorUrl });
    try {
      await adminPool.query(
        'SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = $1',
        [databaseName],
      );
      await adminPool.query(`DROP DATABASE IF EXISTS "${databaseName}"`);
    } finally {
      await adminPool.end();
    }
  }
  if (priorDatabaseUrl === undefined) {
    delete process.env.TRAPMAP_DATABASE_URL;
  } else {
    process.env.TRAPMAP_DATABASE_URL = priorDatabaseUrl;
  }
}

describe.skipIf(!coordinatorUrl)('retrieval promptfoo output matches committed snapshot', () => {
  beforeAll(async () => {
    await provision();
  }, 120_000);

  afterAll(async () => {
    await teardown();
  }, 60_000);

  it('reproduces the smoke snapshot per-case', async () => {
    const config = getSnapshotSuiteConfigs().find((c) => c.suiteId === 'retrieval');
    expect(config).toBeDefined();
    expect(config!.opts.tier).toBe('smoke');

    const { report, caseCount } = await runSuiteWithPromptfoo(retrievalBridge, config!.opts);
    const entries = config!.extract(report).sort((a, b) => a.caseId.localeCompare(b.caseId));

    const snapshot = suiteSnapshotSchema.parse(
      JSON.parse(readFileSync(snapshotFilePath('retrieval'), 'utf8')),
    );

    expect(snapshot.cases.length).toBeGreaterThan(0);
    expect(caseCount).toBe(snapshot.cases.length);
    expect(entries).toEqual(snapshot.cases);
  }, 120_000);
});
